<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api, type Row } from '../api'; import { origins, date } from '../utils'; import AsyncPanel from '../components/AsyncPanel.vue'; import StatusBadge from '../components/StatusBadge.vue'; import JsonDetails from '../components/JsonDetails.vue'
const data = ref<Row>({}), loading = ref(false), error = ref('')
async function load() { loading.value=true; error.value=''; try { data.value=await api.dashboard() } catch(e) { error.value=(e as Error).message } finally { loading.value=false } }
const count = (v: unknown) => Array.isArray(v) ? v.length : typeof v === 'number' ? v : '—'
onMounted(load)
</script>
<template><AsyncPanel :loading="loading" :error="error" @retry="load"><div class="section-heading"><h2>工作空间快照</h2><button class="button secondary" @click="load">刷新数据 ↻</button></div><div class="metric-grid four"><div v-for="[key,label] in [['providers','数据提供方'],['assets','已注册资产'],['versions','资产版本'],['contracts','试交付合同']]" :key="key" class="metric"><span>{{ label }}</span><strong>{{ count(data[key]) }}</strong><small>当前 Registry 记录</small></div></div><div class="two-column wide-left"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">SEPARATE EVIDENCE LEDGERS</p><h2>履约观测 · 按来源分账</h2></div></div><div v-for="origin in origins" :key="origin.value" class="origin-row"><div><b>{{ origin.label }}</b><code>{{ origin.value }}</code><p>{{ origin.note }}</p></div><div v-if="origin.value!=='simulated'" class="origin-counts"><span v-for="state in ['SUCCESS','FAILURE','PENDING','UNKNOWN','DISPUTED']" :key="state"><b>{{ data.status_counts_by_origin?.[origin.value]?.[state] ?? 0 }}</b><small>{{ ({SUCCESS:'成功',FAILURE:'失败',PENDING:'待确认',UNKNOWN:'未知',DISPUTED:'争议'} as Record<string,string>)[state] }}</small></span></div><div v-else class="muted small">{{ data.simulated?.rows ?? '—' }} 条模拟估值记录覆盖<br>不作为当前本地交付合同计数</div></div><p class="footnote">上方三种来源独立统计，不生成无来源说明的“全平台信用”。模拟数据仅显示已接入覆盖窗口。</p></section><section class="panel"><p class="eyebrow">LOCAL NODES</p><h2>数据空间节点</h2><div v-for="(node,i) in (data.nodes ?? [])" :key="i" class="node-row"><div><strong>{{ node.name ?? node.role ?? node.node_id }}</strong><p>{{ node.url ?? node.address }}</p></div><StatusBadge :value="node.status ?? (node.healthy ? 'HEALTHY' : 'UNKNOWN')"/></div><p v-if="!data.nodes?.length" class="muted">暂无节点健康记录</p><div class="notice">节点可连通不等于生产隔离或真实企业身份认证。</div></section></div><section class="panel"><div class="panel-heading"><h2>最近评估记录</h2><RouterLink to="/audit" class="text-link">查看全部报告 →</RouterLink></div><div class="table-wrap"><table><thead><tr><th>报告</th><th>资产 / 版本</th><th>任务 / 类型</th><th>评估时点</th><th>状态</th></tr></thead><tbody><tr v-for="r in (data.recent_reports ?? [])" :key="r.report_id"><td><RouterLink :to="`/audit?report=${encodeURIComponent(r.report_id)}`">{{ r.report_id }}</RouterLink></td><td>{{ r.asset_id ?? '—' }}<small>{{ r.asset_version ?? r.version }}</small></td><td>{{ r.task_id ?? r.kind ?? r.interface }}</td><td>{{ date(r.as_of_time ?? r.created_at) }}</td><td><StatusBadge :value="r.status"/></td></tr><tr v-if="!data.recent_reports?.length"><td colspan="5" class="empty-cell">尚无评估。完成交付后可前往信用或价值页评估。</td></tr></tbody></table></div></section><JsonDetails :data="data" title="核对总览 API 数据来源"/></AsyncPanel></template>
